                <div class="timeline-header">
                  <span class="title">{{ formData.school || '未填写' }}</span>
                  <span class="time">{{ formData.schoolStart || '' }} - {{ formData.schoolEnd || '' }}</span>
                </div>
                <p><span class="label">专业：</span>{{ formData.major || '未填写' }}</p>
