      }
      result.push({ text: `经验匹配：${data.experience}(${expMap[data.experience] || '继续积累经验'})`, type: 'info' })
    }
    
    if (data.education && requiredSkills.length > 0) {
      const eduReqs = {
        '前端开发': ['大专', '本科'],
        '后端开发': ['本科', '硕士'],
        '数据分析师': ['本科', '硕士'],
        'AI算法工程师': ['硕士', '博士'],
