      if (acceptableEdu.includes(data.education)) {
        result.push({ text: `✅ 学历符合岗位要求：${data.education}`, type: 'success' })
      } else {
        result.push({ text: `⚠️ 建议补充相关学历背景或突出实践经验`, type: 'warning' })
      }
    }
    
    if (data.residence) {
      result.push({ text: `📍 工作地点：${data.residence}，将匹配当地岗位`, type: 'info' })
    }
    
    return result
  } else {
    const result = []
    
