/* 简历评分面板样式 */
.score-panel {
  width: 320px;
  margin-bottom: 20px;
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.score-card {
  background: linear-gradient(135deg, rgba(74, 158, 255, 0.1), rgba(0, 212, 170, 0.1));
  border: 1px solid rgba(74, 158, 255, 0.3);
  border-radius: 20px;
  padding: 20px;
  position: relative;
  overflow: hidden;
}

.score-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, #4a9eff, #00d4aa);
}

.score-circle {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: rgba(15, 25, 55, 0.8);
  border: 3px solid rgba(74, 158, 255, 0.5);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: 0 auto 15px;
  position: relative;
}

.score-circle.excellent {
  border-color: #00d4aa;
  box-shadow: 0 0 30px rgba(0, 212, 170, 0.4);
}

.score-circle.good {
  border-color: #4a9eff;
  box-shadow: 0 0 30px rgba(74, 158, 255, 0.4);
}

.score-circle.normal {
  border-color: #ffc107;
  box-shadow: 0 0 30px rgba(255, 193, 7, 0.4);
}

.score-circle.pending {
  border-color: #ff9800;
  box-shadow: 0 0 30px rgba(255, 152, 0, 0.4);
}

.score-value {
  font-size: 32px;
  font-weight: 700;
  color: #fff;
  line-height: 1;
}

.score-max {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.5);
}

.score-info {
  text-align: center;
  margin-bottom: 15px;
}

.score-label {
  color: rgba(255, 255, 255, 0.7);
  font-size: 13px;
  margin-bottom: 5px;
}

.score-level {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
}

.score-level.excellent {
  background: rgba(0, 212, 170, 0.2);
  color: #00d4aa;
}

.score-level.good {
  background: rgba(74, 158, 255, 0.2);
  color: #4a9eff;
}

.score-level.normal {
  background: rgba(255, 193, 7, 0.2);
  color: #ffc107;
}

.score-level.pending {
  background: rgba(255, 152, 0, 0.2);
  color: #ff9800;
}

.score-details {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.score-item {
  display: flex;
  align-items: center;
  gap: 10px;
}

.item-name {
  width: 60px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.6);
}

.item-bar {
  flex: 1;
  height: 6px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
  overflow: hidden;
}

.item-progress {
  height: 100%;
  background: linear-gradient(90deg, #4a9eff, #00d4aa);
  border-radius: 3px;
  transition: width 0.5s ease;
}

.item-score {
  width: 30px;
  text-align: right;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.8);
}

.quick-actions {
  display: flex;
  gap: 10px;
}

.action-btn {
  flex: 1;
  padding: 12px;
  border: none;
  border-radius: 12px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.3s ease;
}

.action-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.action-btn.smart-optimize {
  background: linear-gradient(135deg, #a855f7, #4a9eff);
  color: #fff;
  box-shadow: 0 4px 15px rgba(168, 85, 247, 0.4);
}

.action-btn.smart-optimize:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(168, 85, 247, 0.6);
}

.action-btn.quick-save {
  background: rgba(74, 158, 255, 0.2);
  color: #4a9eff;
  border: 1px solid rgba(74, 158, 255, 0.3);
}

.action-btn.quick-save:hover:not(:disabled) {
  background: rgba(74, 158, 255, 0.3);
}

.action-btn.quick-generate {
  background: rgba(0, 212, 170, 0.2);
  color: #00d4aa;
  border: 1px solid rgba(0, 212, 170, 0.3);
}

.action-btn.quick-generate:hover:not(:disabled) {
  background: rgba(0, 212, 170, 0.3);
}

/* 岗位匹配度仪表盘 */
.match-dashboard {
  display: flex;
  gap: 15px;
  margin-bottom: 15px;
  padding: 15px;
  background: rgba(15, 25, 55, 0.4);
  border-radius: 12px;
  border: 1px solid rgba(74, 158, 255, 0.2);
}

.match-ring {
  position: relative;
  width: 100px;
  height: 100px;
  flex-shrink: 0;
}

.match-ring svg {
  width: 100%;
  height: 100%;
  transform: rotate(0deg);
}

.match-progress {
  transition: stroke-dasharray 0.5s ease;
  filter: drop-shadow(0 0 6px currentColor);
}

.match-value {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
}

.match-value span {
  display: block;
  font-size: 20px;
  font-weight: 700;
  color: #fff;
}

.match-value small {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.6);
}

.match-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  justify-content: center;
}

.match-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.match-label {
  width: 32px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.6);
}

.match-bar {
  flex: 1;
  height: 4px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  overflow: hidden;
}

.match-progress-bar {
  height: 100%;
  border-radius: 2px;
  transition: width 0.5s ease;
}

.match-progress-bar.skill {
  background: linear-gradient(90deg, #4a9eff, #00d4aa);
}

.match-progress-bar.edu {
  background: linear-gradient(90deg, #a855f7, #4a9eff);
}

.match-progress-bar.city {
  background: linear-gradient(90deg, #ffc107, #ff9800);
}

.match-progress-bar.exp {
  background: linear-gradient(90deg, #00d4aa, #4a9eff);
}

.match-score {
  width: 35px;
  text-align: right;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.8);
}

.ai-section {
  width: 320px;
  background: rgba(10, 20, 45, 0.4);
  border: 1px solid rgba(74, 158, 255, 0.2);
  border-radius: 20px;
  padding: 25px;
  position: relative;
  overflow: hidden;
}

.ai-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(74, 158, 255, 0.5), transparent);
}

.section-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 20px;
}

.header-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
