    flex-direction: column;
  }
  
  .step-nav {
    width: 100%;
  }
  
  .step-item {
    display: inline-flex;
    margin-right: 20px;
  }
  
  .ai-section {
    width: 100%;
  }
}

@media (max-width: 700px) {
  .form-row {
    flex-direction: column;
  }
  
  .page-header {
    flex-direction: column;
    align-items: flex-start;
  }
}

.resume-modal {
