/* ===== 3D Immersive Zone ===== */
.immersive-zone {
  position: relative;
  width: 100%;
  min-height: 420px;
  padding: 60px 40px 80px;
  perspective: 1200px;
  z-index: 10;
}

/* 镜面反射平台 */
.reflective-platform {
  position: absolute;
  bottom: 0;
  left: 5%;
  right: 5%;
  height: 180px;
  background: linear-gradient(180deg, 
    rgba(30, 20, 60, 0) 0%, 
    rgba(60, 40, 100, 0.15) 30%, 
    rgba(40, 30, 80, 0.25) 100%);
  transform: perspective(800px) rotateX(65deg);
  transform-origin: center top;
  border-radius: 50% 50% 0 0 / 30px;
  filter: blur(2px);
  opacity: 0.6;
  pointer-events: none;
  z-index: 0;
}

.reflective-platform::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, 
    transparent 5%, 
    rgba(138, 100, 255, 0.6) 30%, 
    rgba(100, 150, 255, 0.8) 50%, 
    rgba(138, 100, 255, 0.6) 70%, 
    transparent 95%);
  box-shadow: 0 0 30px rgba(138, 100, 255, 0.5);
}

/* 光束效果 */
.light-beams {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 1;
}

.beam {
  position: absolute;
  width: 120px;
  height: 100%;
  top: 0;
  opacity: 0.15;
  filter: blur(30px);
}

.beam-1 {
  left: 15%;
  background: linear-gradient(180deg, 
    rgba(138, 100, 255, 0.4) 0%, 
    rgba(138, 100, 255, 0.1) 50%, 
    transparent 100%);
  transform: rotate(-8deg);
  animation: beamFlicker1 6s ease-in-out infinite;
}

.beam-2 {
  left: 50%;
  background: linear-gradient(180deg, 
    rgba(100, 180, 255, 0.3) 0%, 
    rgba(100, 180, 255, 0.08) 40%, 
    transparent 100%);
  transform: rotate(2deg);
  width: 180px;
  animation: beamFlicker2 8s ease-in-out infinite;
}

.beam-3 {
  right: 20%;
  background: linear-gradient(180deg, 
    rgba(180, 120, 255, 0.35) 0%, 
    rgba(180, 120, 255, 0.1) 45%, 
    transparent 100%);
  transform: rotate(-5deg);
  animation: beamFlicker3 7s ease-in-out infinite;
}

@keyframes beamFlicker1 {
  0%, 100% { opacity: 0.15; }
  50% { opacity: 0.25; }
}

@keyframes beamFlicker2 {
  0%, 100% { opacity: 0.12; }
  50% { opacity: 0.2; }
}

@keyframes beamFlicker3 {
  0%, 100% { opacity: 0.18; }
  50% { opacity: 0.28; }
}

/* 漂浮光粒子 */
.floating-particles {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.particle {
  position: absolute;
  width: var(--particle-size, 3px);
  height: var(--particle-size, 3px);
  background: var(--particle-color, #8a64ff);
  border-radius: 50%;
  opacity: 0;
  box-shadow: 0 0 10px var(--particle-color, #8a64ff), 0 0 20px var(--particle-color, #8a64ff);
  animation: particleFloat var(--animation-duration, 4s) ease-in-out var(--animation-delay, 0s) infinite;
}

@keyframes particleFloat {
  0% { 
    opacity: 0; 
    transform: translateY(20px) scale(0.5); 
  }
  20% { 
    opacity: 0.8; 
  }
  80% { 
    opacity: 0.6; 
  }
  100% { 
    opacity: 0; 
    transform: translateY(-40px) scale(1); 
  }
}

/* 3D弧形卡片容器 */
.cards-3d-container {
  position: relative;
  z-index: 5;
}

.cards-arc {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  gap: 30px;
  padding-bottom: 60px;
}

/* 弧形倾斜容器 */
.arc-tilt {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 90%;
  height: 100px;
  background: linear-gradient(180deg, 
    transparent 0%, 
    rgba(100, 80, 160, 0.08) 50%, 
    rgba(80, 60, 140, 0.12) 100%);
  border-radius: 50%;
  filter: blur(15px);
  opacity: 0.7;
  pointer-events: none;
}

/* 3D卡片基础样式 */
.bottom-card-3d {
  position: relative;
  width: 240px;
  cursor: pointer;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94), filter 0.5s ease;
  animation: card3dFadeIn 0.8s ease-out var(--card-delay, 0s) both;
}

@keyframes card3dFadeIn {
  from { 
    opacity: 0; 
    transform: translateY(60px) scale(0.8);
    filter: blur(10px);
  }
  to { 
    opacity: 1; 
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

/* 弧形位置 - 中间卡片最高，两侧渐低 */
.pos-0 { 
  transform: translateY(30px) rotateY(25deg);
}
.pos-1 { 
  transform: translateY(15px) rotateY(12deg);
}
.pos-2 { 
  transform: translateY(0) rotateY(0deg);
  z-index: 10;
}
.pos-3 { 
  transform: translateY(15px) rotateY(-12deg);
}
.pos-4 { 
  transform: translateY(30px) rotateY(-25deg);
}

/* 悬停效果 */
.bottom-card-3d:hover {
  transform: translateY(-20px) rotateY(0deg) scale(1.08) !important;
  filter: brightness(1.1);
  z-index: 20;
}

.pos-2:hover {
  transform: translateY(-25px) rotateY(0deg) scale(1.1) !important;
}

/* 玻璃底座 */
.card-base {
  position: absolute;
  bottom: -10px;
  left: 50%;
  transform: translateX(-50%);
  width: 180px;
  height: 20px;
  z-index: 0;
}

.base-reflection {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  height: 30px;
  background: radial-gradient(ellipse at center top, 
    rgba(var(--theme-rgb), 0.4) 0%, 
    rgba(var(--theme-rgb), 0.2) 40%, 
    transparent 70%);
  filter: blur(8px);
  opacity: 0.6;
}

.base-glow {
  position: absolute;
  bottom: 5px;
  left: 50%;
  transform: translateX(-50%);
  width: 60%;
  height: 4px;
  background: linear-gradient(90deg, 
    transparent, 
    var(--theme-color), 
    transparent);
  box-shadow: 0 0 20px var(--theme-color), 0 0 40px var(--theme-color);
  opacity: 0.8;
  border-radius: 50%;
  animation: baseGlowPulse 3s ease-in-out infinite;
}

@keyframes baseGlowPulse {
  0%, 100% { opacity: 0.6; transform: translateX(-50%) scaleX(0.8); }
  50% { opacity: 1; transform: translateX(-50%) scaleX(1); }
}

/* 玻璃卡片主体 */
.card-glass {
  position: relative;
  background: linear-gradient(145deg, 
    rgba(20, 18, 45, 0.75) 0%, 
    rgba(30, 25, 55, 0.65) 50%, 
    rgba(15, 12, 35, 0.8) 100%);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: 20px;
  padding: 30px 25px 25px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 
    0 8px 32px rgba(0, 0, 0, 0.4),
    0 0 40px rgba(var(--theme-rgb), 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
  transition: all 0.4s ease;
}

.bottom-card-3d:hover .card-glass {
  border-color: rgba(var(--theme-rgb), 0.4);
  box-shadow: 
    0 20px 60px rgba(0, 0, 0, 0.5),
    0 0 60px rgba(var(--theme-rgb), 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.15);
}

/* 3D立体图标 */
.icon-3d {
  position: relative;
  width: 64px;
  height: 64px;
  margin-bottom: 20px;
  perspective: 200px;
}

.icon-cube {
  position: relative;
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, 
    rgba(var(--theme-rgb), 0.3) 0%, 
    rgba(var(--theme-rgb), 0.15) 100%);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--icon-color);
  border: 1px solid rgba(var(--theme-rgb), 0.3);
  transform: rotateY(-15deg) rotateX(10deg);
  transition: transform 0.5s ease;
  box-shadow: 
    0 10px 30px rgba(var(--theme-rgb), 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.bottom-card-3d:hover .icon-cube {
  transform: rotateY(0deg) rotateX(0deg) scale(1.1);
  box-shadow: 
    0 15px 40px rgba(var(--theme-rgb), 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.3);
}

.icon-cube svg {
  filter: drop-shadow(0 0 8px var(--icon-color));
}

.icon-glow-ring {
  position: absolute;
  top: -4px;
  left: -4px;
  right: -4px;
  bottom: -4px;
  border-radius: 18px;
  border: 1.5px solid var(--icon-color);
  opacity: 0.4;
  box-shadow: 0 0 15px var(--icon-color);
  animation: ringRotate 4s linear infinite;
}

@keyframes ringRotate {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.icon-shadow {
  position: absolute;
  bottom: -8px;
  left: 50%;
  transform: translateX(-50%);
  width: 50px;
  height: 8px;
  background: radial-gradient(ellipse at center, 
    rgba(var(--theme-rgb), 0.4) 0%, 
    transparent 70%);
  filter: blur(4px);
  opacity: 0.6;
}

/* 卡片标题 */
.card-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: #ffffff;
  margin: 0 0 10px;
  text-shadow: 
    0 0 20px rgba(255, 255, 255, 0.3),
    0 2px 10px rgba(0, 0, 0, 0.5);
  letter-spacing: 0.5px;
  line-height: 1.3;
  transition: all 0.3s ease;
}

.bottom-card-3d:hover .card-title {
  text-shadow: 
    0 0 30px var(--theme-color),
    0 2px 10px rgba(0, 0, 0, 0.5);
}

/* 卡片描述 */
.card-description {
  font-size: 0.78rem;
  color: rgba(220, 230, 255, 0.7);
  margin: 0 0 24px;
  line-height: 1.6;
}

/* 进入按钮 */
.enter-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 22px;
  background: linear-gradient(135deg, 
    rgba(var(--theme-rgb), 0.4) 0%, 
    rgba(var(--theme-rgb), 0.2) 100%);
  border: 1.5px solid rgba(var(--theme-rgb), 0.6);
  border-radius: 30px;
  color: #ffffff;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 1px;
  cursor: pointer;
  overflow: hidden;
  transition: all 0.3s ease;
  align-self: flex-start;
  box-shadow: 
    0 4px 15px rgba(var(--theme-rgb), 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.enter-btn:hover {
  background: linear-gradient(135deg, 
    rgba(var(--theme-rgb), 0.6) 0%, 
    rgba(var(--theme-rgb), 0.4) 100%);
  border-color: var(--theme-color);
  box-shadow: 
    0 6px 25px rgba(var(--theme-rgb), 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.3);
  transform: translateX(5px);
}

.enter-btn svg {
  transition: transform 0.3s ease;
}

.enter-btn:hover svg {
  transform: translateX(4px);
}

.btn-shine {
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, 
    transparent 0%, 
    rgba(255, 255, 255, 0.3) 50%, 
    transparent 100%);
  animation: btnShine 3s ease-in-out infinite;
}

@keyframes btnShine {
  0%, 100% { left: -100%; }
  50% { left: 100%; }
}

/* 玻璃高光 */
.glass-highlight {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 50%;
  background: linear-gradient(180deg, 
    rgba(255, 255, 255, 0.1) 0%, 
    transparent 100%);
  border-radius: 20px 20px 0 0;
  pointer-events: none;
}

/* 卡片特定配色 */
.card-planning .card-glass {
  background: linear-gradient(145deg, 
    rgba(25, 20, 55, 0.75) 0%, 
    rgba(35, 28, 65, 0.65) 50%, 
    rgba(18, 15, 40, 0.8) 100%);
}

.card-ai-resume .card-glass {
  background: linear-gradient(145deg, 
    rgba(15, 25, 35, 0.75) 0%, 
    rgba(20, 35, 45, 0.65) 50%, 
    rgba(12, 20, 28, 0.8) 100%);
}

.card-talent-stat .card-glass {
  background: linear-gradient(145deg, 
    rgba(30, 18, 45, 0.75) 0%, 
    rgba(40, 25, 55, 0.65) 50%, 
    rgba(22, 14, 32, 0.8) 100%);
}

.card-industry-prediction .card-glass {
  background: linear-gradient(145deg, 
    rgba(35, 25, 10, 0.75) 0%, 
    rgba(45, 32, 15, 0.65) 50%, 
    rgba(28, 20, 8, 0.8) 100%);
}

.card-job-recommend .card-glass {
  background: linear-gradient(145deg, 
    rgba(10, 25, 35, 0.75) 0%, 
    rgba(15, 35, 48, 0.65) 50%, 
